  const w=22+i%3*3;c.save();c.translate(Math.round(x/2)*2,Math.round(y/2)*2);c.transform(1,.131,0,1,0,0);
  dot(c,0,-7,w,7,['#232945','#5c6576','#b2b1ad','#553f55'][i%4]);dot(c,5,-12,w-11,6,'#262e4b');dot(c,6,-11,w-14,3,'#7185a0');dot(c,3,0,4,3,'#111626');dot(c,w-7,0,4,3,'#111626');
